const body = $input.item.json.body || $input.item.json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) {
  staticData.sessions = {};
}

// Evento quando o atendente resolve/encerra o ticket no Chatwoot
if (body.event === 'conversation_status_changed' && body.status === 'resolved') {
  const phone = body.meta && body.meta.sender && body.meta.sender.phone_number ? body.meta.sender.phone_number.replace('+', '') : null;

  if (phone) {
    const remoteJid = phone + '@s.whatsapp.net';
    staticData.sessions[remoteJid] = {
      state: 'CSAT_SURVEY',
      context: {},
      attempts: 0,
      updatedAt: new Date().toISOString()
    };

    return [{
      json: {
        action: 'send_csat',
        number: phone,
        responseText: '⭐ *Atendimento Encerrado*\n\nComo você avalia o atendimento que acabou de receber?\n\n1️⃣ *Excelente* 🌟\n2️⃣ *Bom* 👍\n3️⃣ *Regular* 😐\n4️⃣ *Ruim* 👎\n\n_(Digite o número da sua nota)_'
      }
    }];
  }
}

return [];

const body = $input.item.json.body || $input.item.json;

// Ignora mensagens de status ou do proprio bot
if (!body.data || body.data.key.fromMe || !body.data.message) {
  return [];
}

const remoteJid = body.data.key.remoteJid;
if (remoteJid.includes('@g.us')) {
  return [];
}

const pushName = body.data.pushName || 'Cliente';
let text = '';
if (body.data.message.conversation) {
  text = body.data.message.conversation;
} else if (body.data.message.extendedTextMessage && body.data.message.extendedTextMessage.text) {
  text = body.data.message.extendedTextMessage.text;
}

text = text.trim();
const cleanText = text.toLowerCase();

return [{
  json: {
    remoteJid: remoteJid,
    number: remoteJid.replace('@s.whatsapp.net', ''),
    pushName: pushName,
    text: text,
    cleanText: cleanText
  }
}];

const inputData = $('Filtrar & Tratar Mensagem').item.json;
const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) {
  staticData.sessions = {};
}

let session = staticData.sessions[inputData.remoteJid] || { state: 'MAIN_MENU', context: {}, attempts: 0 };

// ==========================================
// 1. SE O CLIENTE ESTÁ COM ATENDENTE HUMANO (SILENCIAMENTO)
// ==========================================
if (session.state === 'HUMAN_AGENT') {
  // Se o cliente digitar #sair ou #menu, permite forçar a volta pro bot
  if (inputData.cleanText === '#sair' || inputData.cleanText === '#menu') {
    session.state = 'MAIN_MENU';
    session.context = {};
    session.attempts = 0;
  } else {
    // Bot fica 100% em silêncio enquanto o atendente fala pelo Chatwoot
    return [];
  }
}

const input = inputData.cleanText;
let responseText = '';
let nextState = session.state;
let sessionData = session.context || {};
let attempts = session.attempts || 0;
let privateNote = null;

// Reset global
if (input === 'menu' || input === 'inicio' || input === 'sair' || input === 'cancelar') {
  session.state = 'MAIN_MENU';
  sessionData = {};
  attempts = 0;
}

function handleInvalidInput(repeatQuestion) {
  attempts++;
  if (attempts >= 3) {
    nextState = 'MAIN_MENU';
    sessionData = {};
    attempts = 0;
    return '⚠️ *Parece que estamos com dificuldades para entender sua resposta.*\n\nO que deseja fazer?\n\nDigite *MENU* para reiniciar o atendimento ou aguarde para falar com um de nossos atendentes.';
  }
  return '⚠️ *Não entendi sua resposta.* (Tentativa ' + attempts + '/3)\n\n' + repeatQuestion;
}

switch (session.state) {
  // ==========================================
  // MENU PRINCIPAL
  // ==========================================
  case 'MAIN_MENU':
    attempts = 0;
    if (input === '1') {
      nextState = 'SUPORTE_LOS';
      responseText = '🔧 *Suporte Técnico*\n\nVamos verificar sua conexão! Por favor, observe as luzes do seu modem/roteador:\n\nA luz com o nome *LOS* (ou PON) está *vermelha* ou *piscando*?\n\n1️⃣ *Sim*\n2️⃣ *Não*';
    } else if (input === '2') {
      nextState = 'FINANCEIRO_MENU';
      responseText = '💰 *Atendimento Financeiro*\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *2ª Via de Boleto / Código PIX*\n2️⃣ *Consultar Faturas em Aberto*\n3️⃣ *Desbloqueio em Confiança (48h)*\n4️⃣ *Falar com Atendente Financeiro*\n\n_(Digite *MENU* para voltar)_';
    } else if (input === '3') {
      nextState = 'COMERCIAL_MENU';
      responseText = '🛒 *Comercial & Planos*\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *Conhecer Planos de Fibra Residencial*\n2️⃣ *Planos Corporativos / Empresas*\n3️⃣ *Simular Upgrade de Velocidade*\n4️⃣ *Falar com Consultor de Vendas*\n\n_(Digite *MENU* para voltar)_';
    } else {
      responseText = 'Olá, *' + inputData.pushName + '*! 👋 Seja bem-vindo ao atendimento do seu Provedor de Internet.\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *Suporte Técnico*\n2️⃣ *Financeiro & 2ª Via*\n3️⃣ *Comercial & Planos*';
    }
    break;

  // ==========================================
  // 1. FLUXO DE SUPORTE TÉCNICO
  // ==========================================
  case 'SUPORTE_LOS':
    if (input === '1' || input === 'sim') {
      nextState = 'HUMAN_AGENT';
      privateNote = '🚨 ALERTA SUPORTE: Cliente relatou luz LOS/PON vermelha (rompimento de fibra óptica). Encaminhado para agendamento de visita técnica.';
      responseText = '🚨 *Identificamos uma falha no sinal da sua fibra óptica!*\n\nComo a luz LOS está vermelha/piscando, nosso sistema já notificou a equipe técnica.\n\n👤 Você foi transferido para nossa fila de suporte. Um técnico vai assumir a conversa em instantes!';
    } else if (input === '2' || input === 'nao' || input === 'não') {
      nextState = 'SUPORTE_REBOOT';
      responseText = '🔄 *Reinicialização do Equipamento*\n\nPor favor, retire o seu roteador da tomada, aguarde *30 segundos* e ligue novamente.\n\nApós os LEDs estabilizarem, sua conexão voltou ao normal?\n\n1️⃣ *Sim, normalizou!*\n2️⃣ *Não, continuo sem internet.*';
    } else {
      responseText = handleInvalidInput('Por favor, responda apenas:\n1️⃣ para *Sim*\n2️⃣ para *Não*\n\nA luz *LOS/PON* está *vermelha* ou *piscando*?');
    }
    break;

  case 'SUPORTE_REBOOT':
    if (input === '1' || input === 'sim') {
      nextState = 'MAIN_MENU';
      sessionData = {};
      responseText = '🎉 *Excelente! Ficamos felizes que sua conexão foi restabelecida!*\n\nSe precisar de mais alguma coisa, basta enviar uma nova mensagem. Tenha um ótimo dia! 👋';
    } else if (input === '2' || input === 'nao' || input === 'não') {
      nextState = 'SUPORTE_WIFI_CHECK';
      responseText = '📶 *Verificação de Wi-Fi vs Cabo*\n\nO problema de lentidão/queda está acontecendo *apenas no Wi-Fi* ou também via cabo de rede?\n\n1️⃣ *Apenas no Wi-Fi*\n2️⃣ *Geral (Wi-Fi e Cabo)*';
    } else {
      responseText = handleInvalidInput('Por favor, responda apenas:\n1️⃣ para *Sim (normalizou)*\n2️⃣ para *Não (continua sem internet)*\n\nA sua internet voltou após reiniciar o roteador?');
    }
    break;

  case 'SUPORTE_WIFI_CHECK':
    if (input === '1') {
      nextState = 'HUMAN_AGENT';
      privateNote = '📶 SUPORTE WI-FI: Cliente com falha isolada no Wi-Fi. Triagem inicial realizada (Reboot não resolveu). Fazer análise de canal/frequência.';
      responseText = '📡 *Encaminhado para Suporte Especializado em Wi-Fi!*\n\nComo o problema é isolado na rede sem fio, transferi seu atendimento para um técnico analisar os canais e frequência do seu roteador.\n\n👤 Um atendente já vai falar com você aqui. Aguarde um momento!';
    } else if (input === '2') {
      nextState = 'SUPORTE_DESCRICAO';
      responseText = '📝 *Descreva o problema*\n\nPor favor, envie uma mensagem descrevendo o que está acontecendo (ex: lentidão, sites específicos que não abrem, quedas frequentes):';
    } else {
      responseText = handleInvalidInput('Por favor, responda:\n1️⃣ para *Apenas no Wi-Fi*\n2️⃣ para *Geral (Wi-Fi e Cabo)*');
    }
    break;

  case 'SUPORTE_DESCRICAO':
    nextState = 'HUMAN_AGENT';
    privateNote = '📋 SUPORTE GERAL: Cliente relatou falha geral (cabo + Wi-Fi). LOS normal. Reboot não resolveu. Relato: ' + inputData.text;
    responseText = '✅ *Diagnóstico concluído e registrado!*\n\nTransferi você para a nossa equipe de suporte com todo o histórico do seu teste.\n\n👤 Aguarde um instante que um de nossos atendentes já vai responder por aqui!';
    break;

  // ==========================================
  // 2. FLUXO FINANCEIRO
  // ==========================================
  case 'FINANCEIRO_MENU':
    if (input === '1') {
      nextState = 'FINANCEIRO_CPF';
      sessionData.financeiroAcao = '2via';
      responseText = '📄 *2ª Via de Boleto / PIX*\n\nPor favor, digite o *CPF do titular do contrato* (apenas números):';
    } else if (input === '2') {
      nextState = 'FINANCEIRO_CPF';
      sessionData.financeiroAcao = 'faturas';
      responseText = '📊 *Consultar Faturas*\n\nPor favor, digite o *CPF do titular do contrato* (apenas números):';
    } else if (input === '3') {
      nextState = 'FINANCEIRO_CPF';
      sessionData.financeiroAcao = 'desbloqueio';
      responseText = '🔓 *Desbloqueio em Confiança (48 horas)*\n\nPor favor, digite o *CPF do titular do contrato* (apenas números):';
    } else if (input === '4') {
      nextState = 'HUMAN_AGENT';
      privateNote = '💰 FINANCEIRO: Cliente solicitou atendimento humano direto com o setor financeiro.';
      responseText = '👤 *Transferindo para o Setor Financeiro...*\n\nAguarde um momento, um de nossos atendentes financeiros já vai assumir seu atendimento por aqui!';
    } else {
      responseText = handleInvalidInput('Por favor, escolha uma opção válida:\n1️⃣ *2ª Via de Boleto / PIX*\n2️⃣ *Consultar Faturas*\n3️⃣ *Desbloqueio em Confiança*\n4️⃣ *Atendente Financeiro*');
    }
    break;

  case 'FINANCEIRO_CPF':
    const cleanCpf = inputData.text.replace(/[^0-9]/g, '');
    if (cleanCpf.length >= 11) {
      const now = new Date();
      const mes = now.getMonth() + 1;
      const ano = now.getFullYear();
      if (sessionData.financeiroAcao === '2via') {
        nextState = 'MAIN_MENU';
        responseText = '🧾 *Fatura Atual Localizada!*\n\n• *Vencimento:* 10/' + mes + '/' + ano + '\n• *Valor:* R$ 89,90\n• *Status:* Aberto\n\n🔑 *Código PIX Copia e Cola:*\n00020126580014br.gov.bcb.pix0136123e4567-e89b-12d3-a456-4266141740005204000053039865802BR5913ISP PROVEDOR6009SAO PAULO62070503***6304E2CA\n\n📄 *Link do Boleto PDF:*\nhttps://meuprovedor.com.br/faturas/' + cleanCpf + '/boleto.pdf\n\n_(Digite *MENU* se precisar de mais alguma coisa)_';
      } else if (sessionData.financeiroAcao === 'desbloqueio') {
        nextState = 'MAIN_MENU';
        responseText = '🔓 *Desbloqueio em Confiança Realizado com Sucesso!*\n\nO sinal da sua conexão de internet foi liberado provisoriamente por *48 horas*.\n\nPor favor, realize o pagamento da fatura pendente neste período para evitar novo bloqueio automático.\n\nTenha um ótimo dia! 👋';
      } else {
        nextState = 'MAIN_MENU';
        responseText = '📊 *Status Financeiro (CPF: ' + cleanCpf + '):*\n\n• *Contrato Ativo:* Fibra 300 Mega\n• *Faturas Pendentes:* 1 fatura (Vencimento: 10/' + mes + ') - R$ 89,90\n\n_(Digite *MENU* para retornar ao menu principal)_';
      }
      sessionData = {};
    } else {
      responseText = handleInvalidInput('⚠️ *CPF inválido.* Por favor, digite o CPF completo com os 11 dígitos:');
    }
    break;

  // ==========================================
  // 3. FLUXO COMERCIAL & PLANOS
  // ==========================================
  case 'COMERCIAL_MENU':
    if (input === '1') {
      nextState = 'COMERCIAL_INTERESSE';
      sessionData.tipoPlano = 'Residencial';
      responseText = '🚀 *Planos de Fibra Óptica Residencial:*\n\n1️⃣ *300 Mega* - R$ 79,90/mês (Wi-Fi 5 incluso)\n2️⃣ *600 Mega* - R$ 99,90/mês (Wi-Fi 6 Ultra incluso)\n3️⃣ *1 Giga* - R$ 139,90/mês (Instalação Grátis + Wi-Fi 6)\n\nDigite o número do plano que mais te interessou (ou *4* para falar com vendedor):';
    } else if (input === '2') {
      nextState = 'HUMAN_AGENT';
      privateNote = '🏢 COMERCIAL: Cliente interessado em Planos Corporativos com IP Fixo e Link Dedicado.';
      responseText = '🏢 *Planos Corporativos & Link Dedicado*\n\nTemos soluções personalizadas com IP Fixo e SLA garantido de 4h.\n\n👤 Transferindo para um consultor corporativo especializado. Aguarde um momento!';
    } else if (input === '3') {
      nextState = 'COMERCIAL_INTERESSE';
      sessionData.tipoPlano = 'Upgrade';
      responseText = '⚡ *Upgrade de Velocidade com Desconto Especial:*\n\n1️⃣ Upgrade para *600 Mega* (+R$ 15,00/mês)\n2️⃣ Upgrade para *1 Giga* (+R$ 35,00/mês)\n\nDigite *1* ou *2* para solicitar o upgrade ou digite *MENU* para voltar:';
    } else if (input === '4') {
      nextState = 'HUMAN_AGENT';
      privateNote = '🛒 COMERCIAL: Cliente solicitou atendimento humano com consultor de vendas.';
      responseText = '👤 *Transferindo para o Setor Comercial...*\n\nUm de nossos consultores de vendas já vai assumir seu atendimento por aqui. Aguarde um instante!';
    } else {
      responseText = handleInvalidInput('Por favor, escolha uma opção:\n1️⃣ *Planos Residenciais*\n2️⃣ *Planos Corporativos*\n3️⃣ *Upgrade de Velocidade*\n4️⃣ *Consultor de Vendas*');
    }
    break;

  case 'COMERCIAL_INTERESSE':
    if (input === '1' || input === '2' || input === '3') {
      nextState = 'COMERCIAL_CEP';
      sessionData.planoEscolhido = input;
      responseText = '📍 *Consulta de Viabilidade Técnica*\n\nPor favor, digite o seu *CEP* (ou nome da sua rua e bairro) para verificarmos a disponibilidade da fibra:';
    } else if (input === '4') {
      nextState = 'HUMAN_AGENT';
      privateNote = '🛒 COMERCIAL: Cliente em dúvida sobre planos. Transferido para consultor de vendas.';
      responseText = '👤 Transferindo para um consultor de vendas. Aguarde um instante!';
    } else {
      responseText = handleInvalidInput('Por favor, escolha o número do plano desejado (1, 2 ou 3):');
    }
    break;

  case 'COMERCIAL_CEP':
    nextState = 'HUMAN_AGENT';
    privateNote = '🔥 LEAD COMERCIAL: Cliente ' + inputData.pushName + ' interessado em ' + (sessionData.tipoPlano || 'Plano') + ' (Opção ' + (sessionData.planoEscolhido || '1') + '). Endereço/CEP informado: ' + inputData.text + '. Fechar venda!';
    responseText = '🎉 *Excelente notícia! Temos cobertura de Fibra no seu endereço!*\n\nRegistrei seu interesse no plano escolhido.\n\n👤 Nosso consultor de vendas já está assumindo este atendimento para finalizar seu cadastro e agendar a instalação!';
    sessionData = {};
    break;

  // ==========================================
  // 4. PESQUISA DE SATISFAÇÃO (CSAT)
  // ==========================================
  case 'CSAT_SURVEY':
    nextState = 'MAIN_MENU';
    sessionData = {};
    responseText = '🙏 *Muito obrigado pelo seu feedback!*\n\nSua avaliação nos ajuda a melhorar nossos serviços continuamente. Se precisar de algo no futuro, basta mandar uma nova mensagem. Tenha um excelente dia! ✨';
    break;

  default:
    nextState = 'MAIN_MENU';
    responseText = 'Olá, *' + inputData.pushName + '*! 👋 Seja bem-vindo ao atendimento do seu Provedor de Internet.\n\nPor favor, digite o número da opção desejada:\n\n1️⃣ *Suporte Técnico*\n2️⃣ *Financeiro & 2ª Via*\n3️⃣ *Comercial & Planos*';
    break;
}

// Salva a sessao atualizada
staticData.sessions[inputData.remoteJid] = {
  state: nextState,
  context: sessionData,
  attempts: attempts,
  updatedAt: new Date().toISOString()
};

return [{
  json: {
    remoteJid: inputData.remoteJid,
    number: inputData.number,
    responseText: responseText,
    privateNote: privateNote,
    payload: {
      number: inputData.number,
      text: responseText
    }
  }
}];
